from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class CrossSectionalMomentum(Strategy):
    rationale = (
        "Cross-sectional momentum exploits the tendency of stocks within a market to "
        "outperform their peers over short periods. This strategy ranks stocks by recent "
        "returns and invests in the top performers."
    )

    def __init__(self, window: int = 20, top_n: int = 5) -> None:
        self._window = window
        self._top_n = top_n

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < (self._window * len(view.symbols)):
            return Signal(information_available_at=stamp, weights={})

        # Calculate daily returns
        history = history.with_columns(
            (pl.col("adj_close") / pl.col("adj_close").shift(1) - 1.0).alias("return")
        )

        # Group by symbol and calculate mean return over the window period
        mean_returns = (
            history.group_by("symbol")
            .agg(pl.col("return").mean().alias("mean_return"))
            .sort("mean_return", descending=True)
            .head(self._top_n)
        )

        if mean_returns.height == 0:
            return Signal(information_available_at=stamp, weights={})

        top_symbols = mean_returns["symbol"].to_list()
        weight = 1.0 / len(top_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in top_symbols},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
